/**
 * Functional interface allowing a lambda that throws checked exceptions.
 */
@FunctionalInterface
interface ThrowingRunnable {
    void run() throws Exception;
}

/**
 * Executes the given {@link ThrowingRunnable}, wrapping any checked exception
 * in a {@link RuntimeException}. This allows test methods to avoid declaring
 * checked exceptions while still failing the test if an unexpected exception
 * occurs.
 */
private static void runUnchecked(ThrowingRunnable runnable) {
    try {
        runnable.run();
    } catch (Exception e) {
        throw new RuntimeException(e);
    }
}

