/**
 * Combined test that reads the full array of mixed‑case literals and verifies the overall
 * composition. This ensures the original mutant (MathMutator at JsonReader.doPeek) remains
 * exercised while avoiding duplicate assertions.
 */
@Test
public void testMixedCaseLiterals_fullArrayCounts() throws IOException {
  JsonReader reader = new JsonReader(reader("[True,TruE,False,FALSE,NULL,nulL]"));
  reader.beginArray();

  int trueCount = 0;
  int falseCount = 0;
  int nullCount = 0;

  while (reader.hasNext()) {
    JsonToken token = reader.peek();
    switch (token) {
      case BOOLEAN:
        if (reader.nextBoolean()) {
          trueCount++;
        } else {
          falseCount++;
        }
        break;
      case NULL:
        reader.nextNull();
        nullCount++;
        break;
      default:
        throw new AssertionError("Unexpected token: " + token);
    }
  }

  reader.endArray();

  assertWithMessage("Array should contain exactly 2 true literals")
      .that(trueCount)
      .isEqualTo(2);
  assertWithMessage("Array should contain exactly 2 false literals")
      .that(falseCount)
      .isEqualTo(2);
  assertWithMessage("Array should contain exactly 2 null literals")
      .that(nullCount)
      .isEqualTo(2);

  assertWithMessage("Reader should be at END_DOCUMENT after processing the full array")
      .that(reader.peek())
      .isEqualTo(JsonToken.END_DOCUMENT);
}

