@Test
public void skipObjectValues() throws IOException {
  JsonReader reader = factory.create("{\"a\":1,\"b\":2}");
  reader.beginObject();
  assertThat(reader.getPreviousPath()).isEqualTo("$.");
  assertThat(reader.getPath()).isEqualTo("$.");
  String unused1 = reader.nextName();
  reader.skipValue();
  assertThat(reader.getPreviousPath()).isEqualTo("$.a");
  assertThat(reader.getPath()).isEqualTo("$.a");
  String unused2 = reader.nextName();
  assertThat(reader.getPreviousPath()).isEqualTo("$.b");
  assertThat(reader.getPath()).isEqualTo("$.b");
}

proposals.refactored:
@Test
public void skipObjectValues() throws IOException {
    JsonReader reader = factory.create("{\"a\":1,\"b\":2}");
    reader.beginObject();

    // Initial state: both previousPath and path should be "$."
    assertPathEquals(reader, "$.", "initial state");

    // Read first name and skip its value
    String unused1 = reader.nextName();
    reader.skipValue();
    // After skipping first value: both paths should be "$.a"
    assertPathEquals(reader, "$.a", "after skipping first value");

    // Read second name
    String unused2 = reader.nextName();
    // After reading second name: both paths should be "$.b"
    assertPathEquals(reader, "$.b", "after reading second name");
}

/**
 * Asserts that {@link JsonReader#getPreviousPath()} and {@link JsonReader#getPath()}
 * are equal to the expected value, providing a clear context message for each assertion.
 *
 * @param reader   the JsonReader under test
 * @param expected the expected path string
 * @param context  description of the test step for which the assertion is made
 */
private void assertPathEquals(JsonReader reader, String expected, String context) {
    assertWithMessage(context + " - previousPath")
        .that(reader.getPreviousPath())
        .isEqualTo(expected);
    assertWithMessage(context + " - path")
        .that(reader.getPath())
        .isEqualTo(expected);
}

