// Helper functional interface and method for assertDoesNotThrow (JUnit 4 compatible)
@FunctionalInterface
private interface ThrowingRunnable {
    void run() throws Exception;
}

private static void assertDoesNotThrow(ThrowingRunnable runnable) {
    try {
        runnable.run();
    } catch (Throwable t) {
        org.junit.Assert.fail("Unexpected exception occurred during the test: " + t);
    }
}

