 * at the expected location for a given JSON array input.
 *
 * @param json                the JSON string to test
 * @param readFirstBoolean    whether the test should read the first boolean value before calling {@code skipValue()}
 * @param expectedLocation    the expected error location string
 * @throws IOException        if an I/O error occurs while creating the reader
 */
private void assertSkipValueFails(String json, boolean readFirstBoolean, String expectedLocation) throws IOException {
    JsonReader reader = new JsonReader(reader(json));
    reader.beginArray();
    if (readFirstBoolean) {
        // Verify the first element is a boolean true.
        assertThat(reader.nextBoolean()).isTrue();
    }
    MalformedJsonException e = assertThrows(MalformedJsonException.class, () -> reader.skipValue());
    assertStrictError(e, expectedLocation);
}

