@Test
public void testIteratorHasNext() {
    Attributes a = new Attributes();
    a.put("Tot", "1");
    a.put("Hello", "2");
    a.put("data-name", "3");

    int seen = iterateAndValidateAttributes(a);
    assertEquals(
            "Expected number of attributes to be " + EXPECTED_ATTRIBUTE_COUNT,
            EXPECTED_ATTRIBUTE_COUNT,
