void testIteratorSkipsInternal_returnsExpectedKeys() {
    Attributes a = new Attributes();
    a.put("One", "One");
    a.put(Attributes.internalKey("baseUri"), "example.com");
    a.put("Two", "Two");
    a.put(Attributes.internalKey("another"), "example.com");

    Iterator<Attribute> it = a.iterator();

    assertTrue(it.hasNext(), "Iterator should have a first element");
    assertEquals(EXPECTED_KEYS[0], it.next().getKey(), "First returned key should be 'One'");

    assertTrue(it.hasNext(), "Iterator should have a second element");
    assertEquals(EXPECTED_KEYS[1], it.next().getKey(), "Second returned key should be 'Two'");

    assertFalse(it.hasNext(), "Iterator should have no more elements after expected keys");
}

